def get_questions_coulomb_extra():
    q = []
    # Ejercicios
    q.append(make_mc('Cargas q1 = 3.0 microC y q2 = -5.0 microC a 0.20 m en vacio (k=9e9). ¿Modulo de la fuerza?', '3.38 N', ['1.69 N', '6.75 N', '0.68 N'], 'F = 9e9 * 3e-6 * 5e-6 / 0.04 = 3.375 N.', 'F = 3.38 N.', 'basic', 1200, 'Aplica la ley de Coulomb con los valores absolutos de las cargas.'))
    q.append(make_mc('Dos cargas identicas a 0.50 m se repelen con fuerza de 0.90 N en el vacio (k=9e9). ¿Valor de cada carga?', '5.0 microC', ['2.5 microC', '10.0 microC', '1.0 microC'], 'q^2 = F*r^2 / k = 0.90 * 0.25 / 9e9 = 2.5e-11 -> q = 5e-6 C = 5 microC.', 'q = 5.0 microC.', 'intermediate', 1240, 'Despeja la carga q igualando F a k*q^2 / r^2.'))
    q.append(make_mc('Si la distancia entre dos cargas puntuales se reduce a la tercera parte, la fuerza de Coulomb:', 'Se multiplica por 9', ['Se multiplica por 3', 'Se reduce a 1/9', 'Se triplica'], 'F proporcional a 1/r^2: (1 / (1/3))^2 = 9.', 'F aumenta 9 veces.', 'basic', 1180, 'Eleva el factor de reduccion de distancia al cuadrado inverso.'))
    q.append(make_mc('Cargas q1 = +2 microC y q2 = +8 microC separadas 1.0 m. ¿A que distancia de q1 la fuerza neta sobre una 3ra carga es cero?', '0.33 m', ['0.50 m', '0.25 m', '0.67 m'], 'k*2/x^2 = k*8/(1-x)^2 -> 1/x = 2/(1-x) -> 1-x = 2x -> 3x = 1 -> x = 0.33 m.', 'x = 0.33 m desde q1.', 'advanced', 1280, 'Iguala las fuerzas de Coulomb que ejercen ambas cargas sobre la carga de prueba.'))
    q.append(make_mc('Fuerza electrostatica entre dos esferas conductoras descargadas y frotadas que intercambian 1.0e13 electrones a 0.10 m (e=1.6e-19, k=9e9):', '2.3 N', ['1.2 N', '4.6 N', '0.58 N'], 'q = 1e13 * 1.6e-19 = 1.6e-6 C. F = 9e9 * (1.6e-6)^2 / 0.01 = 2.304 N.', 'F = 2.3 N.', 'intermediate', 1250, 'Calcula la carga neta multiplicando el numero de electrones por la carga elemental e.'))
    q.append(make_mc('Carga de +10 microC y otra de -10 microC estan en x = -0.10 m y x = +0.10 m. ¿Fuerza sobre q = +1 microC en el origen?', '18.0 N hacia la derecha', ['9.0 N hacia la derecha', '18.0 N hacia la izquierda', '0.0 N en el origen'], 'Ambas fuerzas empujan/atraen hacia +x: F_tot = 2 * (9e9 * 10e-6 * 1e-6 / 0.01) = 2 * 9 = 18 N.', 'F = 18 N hacia +x.', 'advanced', 1290, 'Suma vectorialmente la fuerza de repulsion de la positiva y de atraccion de la negativa.'))
    q.append(make_mc('Dos esferas identicas con cargas +6 microC y -2 microC se tocan y se vuelven a separar. ¿Carga final de cada una?', '+2.0 microC', ['+4.0 microC', '+1.0 microC', '0.0 microC'], 'q_promedio = (+6 - 2) / 2 = +4 / 2 = +2 microC.', 'q = +2 microC.', 'basic', 1190, 'Al tocarse esferas conductoras identicas, la carga neta se reparte equitativamente.'))
    q.append(make_mc('¿Que aceleracion experimenta un electron (m = 9.1e-31 kg, q = 1.6e-19 C) sometido a fuerza electrica de 3.64e-15 N?', '4.0e15 m/s²', ['2.0e15 m/s²', '8.0e15 m/s²', '1.0e15 m/s²'], 'a = F / m = 3.64e-15 / 9.1e-31 = 4.0e15 m/s2.', 'a = 4.0e15 m/s2.', 'intermediate', 1230, 'Aplica la Segunda Ley de Newton dividiendo la fuerza entre la masa del electron.'))
    q.append(make_mc('Fuerza entre dos cargas en el vacio es 100 N. Si se sumergen en un medio de constante dielectrica relativa epsilon_r = 5:', '20 N', ['500 N', '50 N', '10 N'], 'F_medio = F_vacio / epsilon_r = 100 / 5 = 20 N.', 'F = 20 N.', 'intermediate', 1220, 'La permitividad relativa de un dielectrico reduce la fuerza electrica en ese factor.'))
    q.append(make_mc('Carga de 1.0 C equivale a la carga combinada de aproximadamente:', '6.25e18 electrones', ['1.60e19 electrones', '3.12e18 electrones', '6.02e23 electrones'], 'N = 1.0 / 1.602e-19 = 6.24e18 electrones.', 'N = 6.25e18 electrones.', 'basic', 1180, 'Divide un Coulomb entre la magnitud de la carga fundamental del electron.'))
    # Teoricas
    q.append(make_mc('La Ley de Coulomb es valida estrictamente para:', 'Cargas puntuales en reposo relativo', ['Conductores de cualquier forma en movimiento', 'Cargas en movimiento con corrientes elevadas', 'Campos magneticos dipolares intensos'], 'Valida para electrostatica de cargas puntuales o esfericas estaticas.', 'Cargas puntuales estaticas.', 'basic', 1170, '¿Que condicion cinematica exige la electrostatica clasica de Coulomb?'))
    q.append(make_mc('El principio de conservacion de la carga electrica postula que:', 'La carga neta total de un sistema aislado es constante', ['Las cargas positivas pueden destruirse espontaneamente', 'La carga de cada cuerpo no puede variar jamas', 'No se pueden transferir electrones entre cuerpos'], 'La carga no se crea ni destruye, solo se redistribuye.', 'Carga neta se conserva en sistemas aislados.', 'basic', 1160, '¿Que ocurre con la suma algebraica de todas las cargas en un sistema cerrado?'))
    q.append(make_mc('La cuantizacion de la carga electrica significa que:', 'Cualquier carga es multiplo entero de la carga elemental e', ['La carga solo existe en magnitudes continuas infinitas', 'Todos los cuerpos tienen carga estrictamente nula', 'La carga depende linealmente de la velocidad del cuerpo'], 'q = n * e, con n entero.', 'Carga existe en paquetes discretos de e.', 'basic', 1170, '¿Puede un cuerpo aislado tener una fraccion decimal como 0.5 electrones?'))
    q.append(make_mc('El par de fuerzas electrostáticas entre dos cargas de signos contrarios es:', 'Atractivo y cumple la Tercera Ley de Newton', ['Repulsivo y no cumple la Tercera Ley de Newton', 'Atractivo y de diferente magnitud en cada una', 'Nulo debido a la cancelacion mutua de signos'], 'Signos opuestos se atraen con fuerzas iguales y opuestas.', 'Fuerzas atractivas de igual modulo y sentidos contrarios.', 'basic', 1160, 'Recuerda que la interaccion mutua siempre obedece accion y reaccion.'))
    q.append(make_mc('La constante k de Coulomb en el Sistema Internacional se expresa como:', '1 / (4 * pi * epsilon_0)', ['4 * pi * epsilon_0', 'epsilon_0 / (4 * pi)', 'mu_0 / (4 * pi)'], 'k = 1 / (4 * pi * epsilon_0) aprox 8.99e9 N*m2/C2.', 'k = 1 / (4*pi*epsilon_0).', 'basic', 1160, '¿Como se vincula la constante k con la permitividad del vacio epsilon_0?'))
    q.append(make_mc('Al frotar una varilla de vidrio con seda, la varilla adquiere carga positiva porque:', 'Cede electrones a la tela de seda', ['Absorbe protones del tejido de seda', 'Destruye electrones de su propia estructura', 'Crea protones por efecto de la friccion'], 'En solidos solo los electrones tienen movilidad para transferirse.', 'Los electrones pasan del vidrio a la seda.', 'basic', 1150, '¿Cuales particulas subatomicas tienen movilidad para pasar de un material a otro?'))
    q.append(make_mc('La constante dielectrica relativa de un medio material aislante es siempre:', 'Mayor o igual a uno (epsilon_r >= 1)', ['Menor que uno en todo aislante', 'Estrictamente negativa en liquidos', 'Igual a cero para conductores ideales'], 'En cualquier medio material la fuerza electrostatica disminuye respecto al vacio (epsilon_r >= 1).', 'epsilon_r >= 1.', 'intermediate', 1220, '¿Aumenta o debilita la polarizacion del medio dielectrico la fuerza entre cargas?'))
    q.append(make_mc('El principio de superposicion electrostatica establece que la fuerza sobre una carga:', 'Es la suma vectorial de las fuerzas individuales de las demas', ['Es el producto escalar de las fuerzas individuales', 'Es igual a la fuerza de la carga mas cercana unicamente', 'Es el promedio aritmetico de las fuerzas actuantes'], 'F_tot = suma de F_i vectoriales independientes.', 'Suma vectorial de fuerzas individuales.', 'basic', 1160, '¿Como se combinan las fuerzas de varias cargas sobre un punto?'))
    q.append(make_mc('Si una carga positiva Q se ubica en el centro de un cascaron esferico conductor descargado:', 'Se induce carga -Q en la cara interna y +Q en la externa', ['El cascaron queda uniformemente negativo en todo volumen', 'La carga interna Q es neutralizada y desaparece', 'No se induce carga alguna por estar descargado'], 'Induccion electrostatica: campo interno nulo exige -Q adentro y +Q afuera.', 'Induce -Q adentro y +Q afuera.', 'advanced', 1270, 'Aplica la condicion de campo nulo en el interior del metal conductor en equilibrio.'))
    q.append(make_mc('La unidad del Sistema Internacional para la carga electrica es el Coulomb (C), definido como:', 'Ampere por segundo (A·s)', ['Volt sobre Ohm (V/Omega)', 'Joule por segundo (J/s)', 'Newton sobre metro (N/m)'], 'I = q/t => 1 C = 1 A * 1 s.', 'Coulomb = Ampere * segundo.', 'basic', 1140, 'Despeja la carga a partir de la definicion de corriente electrica I = q/t.'))
    return q

def get_questions_campo_electrico_extra():
    q = []
    # Ejercicios
    q.append(make_mc('Carga puntual Q = 5.0 nC crea campo a 0.30 m en el vacio (k=9e9). ¿Modulo de E?', '500 N/C', ['150 N/C', '1500 N/C', '50 N/C'], 'E = 9e9 * 5e-9 / (0.3)^2 = 45 / 0.09 = 500 N/C.', 'E = 500 N/C.', 'basic', 1200, 'Aplica E = k*Q / r^2 dividiendo entre el radio al cuadrado.'))
    q.append(make_mc('Campo electrico uniforme E = 4000 N/C empuja carga q = 2.5 microC. ¿Fuerza electrica?', '0.010 N', ['0.020 N', '0.005 N', '0.040 N'], 'F = q * E = 2.5e-6 * 4000 = 0.010 N.', 'F = 0.010 N.', 'basic', 1180, 'Multiplica la intensidad del campo por la carga electrica.'))
    q.append(make_mc('Un proton (m=1.67e-27 kg, q=1.6e-19 C) en campo E = 2.0e4 N/C. ¿Aceleracion que sufre?', '1.92e12 m/s²', ['3.84e12 m/s²', '9.60e11 m/s²', '1.20e11 m/s²'], 'a = q*E / m = 1.6e-19 * 2e4 / 1.67e-27 = 1.916e12 m/s2.', 'a = 1.92e12 m/s2.', 'intermediate', 1240, 'Calcula la fuerza F = q*E y dividela por la masa del proton.'))
    q.append(make_mc('Dos placas paralelas separadas 0.02 m tienen tension de 200 V. ¿Campo electrico uniforme?', '10000 V/m', ['5000 V/m', '20000 V/m', '4000 V/m'], 'E = Delta V / d = 200 / 0.02 = 10000 V/m.', 'E = 10000 V/m.', 'basic', 1190, 'Divide la diferencia de potencial entre la distancia entre placas.'))
    q.append(make_mc('A que distancia de una carga Q = 4.0 microC el campo vale 9000 N/C en vacio? (k=9e9):', '2.0 m', ['1.0 m', '4.0 m', '0.5 m'], 'r^2 = k*Q / E = 9e9 * 4e-6 / 9000 = 36000 / 9000 = 4 -> r = 2.0 m.', 'r = 2.0 m.', 'intermediate', 1230, 'Despeja r en la formula E = k*Q / r^2 sacando raiz cuadrada.'))
    q.append(make_mc('Gota de masa 3.2e-14 kg flota en equilibrio en campo vertical E = 2.0e5 N/C (g = 10 m/s2). ¿Carga q?', '1.6e-18 C', ['3.2e-18 C', '8.0e-19 C', '6.4e-18 C'], 'q*E = m*g -> q = 3.2e-14 * 10 / 2e5 = 3.2e-13 / 2e5 = 1.6e-18 C.', 'q = 1.6e-18 C.', 'advanced', 1270, 'Iguala la fuerza electrica ascendente con el peso descendente de la gota.'))
    q.append(make_mc('Flujo electrico a traves de una superficie cerrada que encierra carga neta q = 8.85 nC (epsilon_0 = 8.85e-12):', '1000 N·m²/C', ['500 N·m²/C', '2000 N·m²/C', '100 N·m²/C'], 'Ley de Gauss: Phi = q_enc / epsilon_0 = 8.85e-9 / 8.85e-12 = 1000 N*m2/C.', 'Phi = 1000 N*m2/C.', 'intermediate', 1250, 'Aplica la ley de Gauss dividiendo la carga encerrada entre epsilon_0.'))
    q.append(make_mc('Dos cargas iguales de +2.0 microC separadas 2.0 m. ¿Campo electrico en el punto medio exacto?', '0 N/C', ['9000 N/C', '18000 N/C', '36000 N/C'], 'Por simetria, los campos creados son iguales en modulo y sentidos opuestos: E_tot = 0.', 'E = 0 N/C por cancelacion vectorial.', 'basic', 1170, 'Los vectores de campo apuntan alejandose de cada carga: ¿hacia donde van en el punto medio?'))
    q.append(make_mc('En esfera conductora en equilibrio electrostático de radio 0.10 m con carga 20 nC, ¿campo en r = 0.05 m (adentro)?', '0 N/C', ['18000 N/C', '9000 N/C', '36000 N/C'], 'En el interior de cualquier conductor en equilibrio electrostático el campo es estrictamente cero.', 'E = 0 en el interior del conductor.', 'basic', 1180, 'Recuerda el comportamiento del campo electrico estatico dentro de un metal.'))
    q.append(make_mc('Particula alfa (q = +2e) entra en campo E uniforme de 5000 N/C. ¿Modulo de la fuerza electrica?', '1.6e-15 N', ['8.0e-16 N', '3.2e-15 N', '4.0e-16 N'], 'F = q*E = 2 * 1.6e-19 * 5000 = 1.6e-15 N.', 'F = 1.6e-15 N.', 'intermediate', 1220, 'Multiplica dos cargas elementales por la intensidad del campo electrico.'))
    # Teoricas
    q.append(make_mc('El campo electrico E en un punto del espacio se define operacionalmente como:', 'La fuerza sobre una carga de prueba positiva dividida entre dicha carga', ['El trabajo necesario para mover una carga unitaria al infinito', 'La variacion temporal del potencial electrostatico vectorial', 'La cantidad neta de carga encerrada en una superficie gaussiana'], 'E = lim F / q_0 cuando q_0 tiende a cero.', 'E = F / q_0.', 'basic', 1160, '¿Que razon de fuerza por unidad de carga define la intensidad de campo?'))
    q.append(make_mc('Las lineas de campo electrico nunca pueden cruzarse en el espacio porque:', 'El campo tendria dos direcciones distintas en un mismo punto', ['La intensidad del campo se volveria infinita en el cruce', 'Las cargas se neutralizarian al tocarse las lineas', 'El flujo electrico a traves de la zona se haria negativo'], 'El vector E es unico y tangente a la linea en cada punto.', 'E tendria dos direcciones simultaneas, lo cual es imposible.', 'basic', 1170, 'El campo electrico es una funcion vectorial univoca en cada posicion.'))
    q.append(make_mc('En el interior de un conductor en equilibrio electrostatico, el campo electrico:', 'Es estrictamente nulo en todos sus puntos internos', ['Es maximo en el centro geometrico del material', 'Aumenta linealmente desde el centro a la periferia', 'Depende de la permeabilidad magnetica del metal'], 'Si hubiera campo interno, los electrones libres se moverian, no habria equilibrio.', 'E = 0 en el interior del conductor en equilibrio.', 'basic', 1170, 'Si hubiera campo electrico interno, ¿estarian las cargas en reposo?'))
    q.append(make_mc('Toda la carga neta de un conductor en equilibrio electrostatico reside en:', 'Su superficie exterior exclusivamente', ['El centro geometrico del conductor solido', 'Distribuida uniformemente por todo el volumen', 'En los puntos de menor curvatura geometrica'], 'Por repulsion mutua, las cargas se alojan en la frontera externa.', 'Toda la carga reside en la superficie exterior.', 'basic', 1180, '¿Hacia donde empuja la repulsion mutua a las cargas libres del metal?'))
    q.append(make_mc('El fenomeno del efecto de las puntas en conductores cargados se debe a que:', 'El campo electrico es mucho mas intenso en zonas de menor radio de curvatura', ['Las puntas concentran electrones de valencia mas pesados', 'El potencial electrico en las puntas es el doble que en la base', 'El aire circundante se comprime fuertemente en las aristas'], 'Menor radio de curvatura implica mayor densidad de carga superficial sigma.', 'Mayor densidad de carga y campo en zonas agudas.', 'intermediate', 1230, '¿Donde se acumula mayor densidad superficial de carga en un conductor irregular?'))
    q.append(make_mc('La Ley de Gauss relaciona el flujo electrico total a traves de una superficie cerrada con:', 'La carga neta total encerrada dividida entre epsilon_0', ['El potencial electrico promedio sobre el area de la superficie', 'La masa total de las cargas que componen el sistema', 'La intensidad de la corriente electrica entrante'], 'Phi_E = Q_encerrada / epsilon_0.', 'Phi = Q_enc / epsilon_0.', 'intermediate', 1220, '¿Que magnitud fisica encerrada determina el flujo neto total?'))
    q.append(make_mc('El campo electrico inmediatamente exterior a la superficie de un conductor cargado es:', 'Perpendicular a la superficie en cada punto', ['Tangente a la superficie del conductor', 'Forma un angulo de 45° con la normal', 'Es estrictamente nulo en el exterior'], 'Si tuviera componente tangencial, habria corriente superficial.', 'E exterior es perpendicular a la superficie.', 'intermediate', 1230, 'Si hubiera componente tangencial, ¿podrian estar las cargas superficiales en reposo?'))
    q.append(make_mc('La jaula de Faraday demuestra el principio de apantallamiento electrostatico, segun el cual:', 'El interior hueco de un conductor queda protegido de campos externos', ['Las ondas sonoras no pueden propagarse en recintos metalicos', 'El voltaje dentro de la jaula se multiplica peligrosamente', 'La carga exterior fluye de inmediato hacia el ocupante'], 'La redistribucion superficial cancela el campo externo en la cavidad.', 'Campo exterior se anula dentro de la cavidad hueca.', 'basic', 1170, '¿Que le ocurre al campo electrico en el interior hueco de una carroceria de auto?'))
    q.append(make_mc('La unidad del campo electrico en el Sistema Internacional puede expresarse indistintamente como:', 'N/C o V/m', ['J/C o W/m', 'N·m o V·s', 'Tesla o Gauss'], '1 N/C = 1 (J/m) / C = 1 (J/C) / m = 1 V/m.', 'N/C o V/m.', 'basic', 1150, 'Relaciona la definicion por fuerza (F/q) con la definicion por voltaje (Delta V / d).'))
    q.append(make_mc('Entre dos placas conductoras paralelas infinitas con densidades de carga opuestas +sigma y -sigma:', 'El campo es uniforme y vale sigma / epsilon_0', ['El campo se duplica en cada placa y se anula al medio', 'El campo decrece con el cuadrado de la separacion', 'El campo es radial convergente al centro geometrico'], 'Los campos de ambas placas se suman uniformemente: sigma / epsilon_0.', 'E = sigma / epsilon_0 uniforme entre placas.', 'advanced', 1260, 'Suma los campos de dos planos cargados de signos opuestos.'))
    return q


def get_questions_potencial_electrico_extra():
    q = []
    # Ejercicios
    q.append(make_mc('Carga puntual Q = 6.0 nC en vacio (k=9e9). ¿Potencial electrostatico a 0.20 m?', '270 V', ['135 V', '540 V', '90 V'], 'V = k*Q / r = 9e9 * 6e-9 / 0.20 = 54 / 0.20 = 270 V.', 'V = 270 V.', 'basic', 1190, 'Aplica la formula V = k*Q / r con el radio lineal.'))
    q.append(make_mc('Trabajo para trasladar q = 3.0 microC entre dos puntos con Delta V = 50 V:', '1.5e-4 J', ['3.0e-4 J', '7.5e-5 J', '1.5e-3 J'], 'W = q * Delta V = 3e-6 * 50 = 1.5e-4 J.', 'W = 1.5e-4 J.', 'basic', 1180, 'Multiplica la carga transportada por la diferencia de potencial.'))
    q.append(make_mc('Campo uniforme E = 2000 V/m. ¿Diferencia de potencial entre dos puntos separados 0.05 m en linea con el campo?', '100 V', ['50 V', '200 V', '40 V'], 'Delta V = E * d = 2000 * 0.05 = 100 V.', 'Delta V = 100 V.', 'basic', 1180, 'Multiplica el campo electrico uniforme por la distancia en su direccion.'))
    q.append(make_mc('Electron (q = -1.6e-19 C) acelerado desde el reposo por Delta V = 500 V. ¿Energia cinetica final?', '500 eV', ['250 eV', '1000 eV', '50 eV'], 'Ek = q * Delta V = 1 e * 500 V = 500 eV = 8.0e-17 J.', 'Ek = 500 eV.', 'basic', 1170, 'Un electron acelerado por un Volt adquiere un electron-Volt de energia.'))
    q.append(make_mc('Energia potencial electrostatica entre dos cargas de 2.0 microC y 5.0 microC a 0.10 m (k=9e9):', '0.90 J', ['0.45 J', '1.80 J', '9.0 J'], 'U = k*q1*q2 / r = 9e9 * 2e-6 * 5e-6 / 0.10 = 0.09 / 0.10 = 0.90 J.', 'U = 0.90 J.', 'intermediate', 1230, 'Divide k por el producto de cargas y entre la distancia simple.'))
    q.append(make_mc('Esfera conductora de radio 0.15 m con carga de 30 nC (k=9e9). ¿Potencial en su superficie?', '1800 V', ['900 V', '3600 V', '2700 V'], 'V = k*Q / R = 9e9 * 30e-9 / 0.15 = 270 / 0.15 = 1800 V.', 'V = 1800 V.', 'intermediate', 1220, 'El potencial en la superficie de la esfera es k*Q / R.'))
    q.append(make_mc('En la misma esfera conductora del ejercicio anterior (R = 0.15 m), ¿potencial en r = 0.05 m (centro)?', '1800 V', ['0 V', '5400 V', '600 V'], 'Todo el volumen de un conductor en equilibrio es equipotencial: V_int = V_sup = 1800 V.', 'V_int = 1800 V.', 'intermediate', 1240, 'Recuerda que dentro del conductor E = 0, por lo que el potencial es constante.'))
    q.append(make_mc('Dos cargas iguales de +4.0 microC separadas 0.40 m. ¿Potencial en el punto medio exacto?', '3.6e5 V', ['1.8e5 V', '0 V', '7.2e5 V'], 'V_tot = 2 * (k*Q / (r/2)) = 2 * (9e9 * 4e-6 / 0.20) = 2 * 1.8e5 = 3.6e5 V.', 'V = 360000 V.', 'intermediate', 1240, 'El potencial es un escalar: se suman algebraicamente los aportes de cada carga.'))
    q.append(make_mc('¿Que velocidad adquiere un proton (m=1.67e-27 kg, q=1.6e-19 C) acelerado por 1000 V desde el reposo?', '4.38e5 m/s', ['2.19e5 m/s', '8.76e5 m/s', '1.09e5 m/s'], '0.5*m*v^2 = q*V -> v = sqrt(2*q*V / m) = sqrt(2 * 1.6e-19 * 1000 / 1.67e-27) = 4.377e5 m/s.', 'v = 4.38e5 m/s.', 'advanced', 1280, 'Iguala la energia potencial electrica cedida a la energia cinetica adquirida.'))
    q.append(make_mc('Diferencia de potencial entre dos superficies equipotenciales es 60 V. Trabajo para mover 0.02 C a lo largo de la misma superficie:', '0.0 J', ['1.2 J', '60 J', '3000 J'], 'Al moverse a lo largo de una equipotencial Delta V = 0 => W = q * 0 = 0.', 'W = 0 sobre una equipotencial.', 'basic', 1160, 'Sobre una superficie equipotencial, ¿cambia el potencial electrico?'))
    # Teoricas
    q.append(make_mc('El potencial electrico V en un punto es una magnitud de naturaleza:', 'Escalar que representa energia por unidad de carga', ['Vectorial tangente a las lineas de fuerza', 'Tensorial dependiente del area de prueba', 'Adimensional en el Sistema Internacional'], 'V = U / q es escalar medido en Joules por Coulomb (Volts).', 'V es una magnitud escalar.', 'basic', 1150, '¿Tiene el potencial electrico una direccion espacial como una flecha?'))
    q.append(make_mc('Una superficie equipotencial se define como el conjunto de puntos donde:', 'El potencial electrostatico tiene exactamente el mismo valor', ['El campo electrico tiene intensidad estrictamente nula', 'La carga electrica acumulada es maxima absoluta', 'Las lineas de campo son paralelas a la superficie'], 'Equipotencial: Delta V = 0 entre cualesquiera dos puntos.', 'Mismo valor de potencial en todos sus puntos.', 'basic', 1150, 'El prefijo equi denota igualdad de potencial.'))
    q.append(make_mc('Las lineas de campo electrico y las superficies equipotenciales:', 'Son perpendiculares entre si en todos los puntos', ['Son paralelas entre si en todos los puntos', 'Forman angulos agudos de 45 grados', 'Coinciden en la misma orientacion espacial'], 'E apunta en la direccion de maximo descenso de V, normal a las equipotenciales.', 'Son siempre perpendiculares entre si.', 'basic', 1170, '¿Como se cortan las lineas de fuerza con las superficies de igual voltaje?'))
    q.append(make_mc('Al desplazarse en el mismo sentido que las lineas de campo electrico, el potencial:', 'Disminuye progresivamente', ['Aumenta progresivamente', 'Permanece estrictamente constante', 'Oscila entre maximos y minimos'], 'Las lineas de campo apuntan hacia potenciales decrecientes: E = - grad V.', 'El potencial disminuye a favor de E.', 'intermediate', 1210, '¿Hacia donde se mueven espontaneamente las cargas positivas liberadas en el campo?'))
    q.append(make_mc('Un conductor en equilibrio electrostático constituye una region:', 'Completamente equipotencial en volumen y superficie', ['Con mayor potencial en el centro que en la piel', 'Con potencial nulo unicamente en las puntas', 'Con voltaje dependiente de la densidad de masa'], 'Como E = 0 en el interior, no hay variacion de potencial: V = cte.', 'El conductor completo es un cuerpo equipotencial.', 'intermediate', 1220, 'Si el campo electrico interno es cero, ¿puede haber diferencia de potencial?'))
    q.append(make_mc('El trabajo realizado por el campo electrostatico sobre una carga en una trayectoria cerrada:', 'Es estrictamente nulo por ser campo conservativo', ['Es maximo positivo proporcional al perimetro', 'Depende de la velocidad a la que se recorra', 'Depende de la presencia de dielectricos externos'], 'El campo electrostatico es conservativo: integral de linea cerrada es cero.', 'W = 0 en trayectorias cerradas (conservativo).', 'intermediate', 1230, '¿Como se comporta el trabajo de una fuerza conservativa en un ciclo cerrado?'))
    q.append(make_mc('La unidad del Sistema Internacional para el potencial electrico es el Volt (V), igual a:', 'Joule sobre Coulomb (J/C)', ['Newton por metro cuadrado', 'Coulomb por segundo (C/s)', 'Watt sobre Ampere cuadrado'], '1 V = 1 J / 1 C.', 'Volt = Joule / Coulomb.', 'basic', 1140, 'Recuerda que el potencial mide la energia por cada unidad de carga transportada.'))
    q.append(make_mc('El electron-volt (eV) es una unidad utilizada comunmente para medir:', 'Energia en fisica atomica y nuclear', ['Diferencia de potencial en aceleradores', 'Intensidad de corriente electronica', 'Carga electrica fraccionaria de quarks'], '1 eV = 1.602e-19 J: unidad de energia.', 'Unidad de energia (1 eV = 1.6e-19 J).', 'basic', 1160, 'Distingue entre la unidad de potencial (Volt) y la de energia (electron-Volt).'))
    q.append(make_mc('Si se traslada una carga testigo entre dos puntos a traves de tres caminos diferentes en un campo estatico:', 'El trabajo realizado es identico en los tres caminos', ['El camino mas corto realiza menor trabajo que los demas', 'El camino con mas curvas consume mayor trabajo neto', 'El trabajo solo existe si la trayectoria es recta'], 'El trabajo es independiente de la trayectoria por ser campo conservativo.', 'Trabajo independiente del camino seguido.', 'intermediate', 1220, '¿Depende el trabajo de una fuerza conservativa del recorrido o solo de los extremos?'))
    q.append(make_mc('La conexion a tierra de un circuito o chasis metalico se define como fijar:', 'El potencial de referencia a cero Volts (V = 0)', ['La corriente total a un valor maximo infinito', 'La resistencia del equipo a un valor infinito', 'El campo electrostatico a 1000 N/C constante'], 'La Tierra actua como reservorio infinito de carga a potencial nulo.', 'Fija el potencial de referencia en cero.', 'basic', 1150, '¿Que nivel de potencial de referencia se toma convencionalmente en el suelo?'))
    return q

def get_questions_circuitos_corriente_extra():
    q = []
    # Ejercicios
    q.append(make_mc('Alambre de cobre (rho = 1.7e-8 ohm·m) tiene L = 50 m y seccion A = 1.0 mm2. ¿Resistencia R?', '0.85 ohm', ['1.70 ohm', '0.43 ohm', '8.50 ohm'], 'R = rho * L / A = 1.7e-8 * 50 / 1e-6 = 0.85 ohm.', 'R = 0.85 ohm.', 'basic', 1200, 'Aplica la ley de Pouillet pasando los milimetros cuadrados a metros cuadrados.'))
