    q.append(make_mc('Ducha electrica de 4400 W conectada a 220 V se usa 15 min diarios. ¿Energia consumida al mes (30 dias)?', '33 kWh', ['66 kWh', '22 kWh', '11 kWh'], 't_tot = 30 * 0.25 h = 7.5 h. E = 4.4 kW * 7.5 h = 33 kWh.', 'E = 33 kWh.', 'intermediate', 1220, 'Calcula las horas mensuales totales y multiplicalas por los kilowatts.'))
