    q.append(make_mc('¿Cuantos electrones atraviesan un foco cada segundo cuando circula corriente de 0.80 A? (e = 1.6e-19 C)', '5.0e18 electrones', ['2.5e18 electrones', '1.0e19 electrones', '8.0e18 electrones'], 'N = I / e = 0.80 / 1.6e-19 = 5.0e18 electrones/s.', 'N = 5.0e18 electrones/s.', 'basic', 1190, 'Divide la corriente entre el valor de la carga de un electron.'))
    q.append(make_mc('Corriente de 3.0 A fluye por resistencia de 10 ohms durante 20 segundos. ¿Calor generado (Joule)?', '1800 J', ['600 J', '900 J', '3600 J'], 'Q = I^2 * R * t = 9 * 10 * 20 = 1800 J.', 'Q = 1800 J.', 'intermediate', 1210, 'Aplica la ley de Joule multiplicando I al cuadrado por R y por el tiempo.'))
